def memo_routes(n):
    cache={0:1}
    def solve(k):
        if k<0:return 0
        if k not in cache:
            left,right=transition(k)
            cache[k]=solve(left)+solve(right)
            record_state(k,cache[k])
        return cache[k]
    return solve(n)
