def measure(solver,n):
    global transition
    original=transition
    expansions=0
    def counted(k):
        nonlocal expansions
        expansions+=1
        return original(k)
    transition=counted
    try:
        answer=solver(n)
    finally:
        transition=original
    return answer,expansions
